    points.sort()
    intersections = set()
    for i in range(1, n):
        for j in range(i + 1, n):
            if points[i] < points[j]:
                if points[i] in intersections or points[j] in intersections:
                    return "yes"
                else:
                    intersections.add(points[i])
                    intersections.add(points[j])
            else:
